package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

type TaxRec struct {
	TrId     string          // PIC X(5) @0 len=5
	TrIncome decimal.Decimal // PIC 9(6)V99 @5 len=8
}

var WsEofFlag string = "N"
var WsTax decimal.Decimal = decimal.NewFromInt(0)
var WsNet decimal.Decimal = decimal.NewFromInt(0)
var WsTotalTax decimal.Decimal = decimal.NewFromInt(0)
var WsCount int64 = 0
var WsIncEd string
var WsTaxEd string
var WsNetEd string
var WsTotalEd string

var taxRec TaxRec
var taxFile *os.File
var taxScanner *bufio.Scanner

func fitDecimal(v decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	sign := v.Sign()
	abs := v.Abs()
	s := abs.StringFixed(scale)
	var intPart, fracPart string
	if scale > 0 {
		parts := strings.SplitN(s, ".", 2)
		intPart = parts[0]
		if len(parts) > 1 {
			fracPart = parts[1]
		} else {
			fracPart = strings.Repeat("0", int(scale))
		}
		if strings.HasPrefix(intPart, "-") {
			intPart = intPart[1:]
		}
		if len(fracPart) < int(scale) {
			fracPart += strings.Repeat("0", int(scale)-len(fracPart))
		}
	} else {
		intPart = s
		if strings.HasPrefix(intPart, "-") {
			intPart = intPart[1:]
		}
		fracPart = ""
	}
	if len(intPart) > intDigits {
		intPart = intPart[len(intPart)-intDigits:]
	}
	var res decimal.Decimal
	var err error
	if scale > 0 {
		combined := intPart + "." + fracPart
		if combined == "" {
			combined = "0." + fracPart
		}
		if strings.HasPrefix(combined, ".") {
			combined = "0" + combined
		}
		res, err = decimal.NewFromString(combined)
		if err != nil {
			res = decimal.NewFromInt(0)
		}
	} else {
		if intPart == "" {
			intPart = "0"
		}
		res, err = decimal.NewFromString(intPart)
		if err != nil {
			res = decimal.NewFromInt(0)
		}
	}
	if sign < 0 {
		res = res.Neg()
	}
	return res
}

func formatEdited(v decimal.Decimal, pic string) string {
	dot := strings.Index(pic, ".")
	var intPic, fracPic string
	if dot >= 0 {
		intPic = pic[:dot]
		fracPic = pic[dot+1:]
	} else {
		intPic = pic
		fracPic = ""
	}
	fDigits := len(fracPic)
	iPlace := 0
	for _, c := range intPic {
		if c == 'Z' || c == '9' {
			iPlace++
		}
	}
	abs := v.Abs()
	rounded := abs.Round(int32(fDigits))
	sFixed := rounded.StringFixed(int32(fDigits))
	var intStr, fracStr string
	if fDigits > 0 {
		parts := strings.SplitN(sFixed, ".", 2)
		intStr = parts[0]
		if len(parts) > 1 {
			fracStr = parts[1]
		} else {
			fracStr = strings.Repeat("0", fDigits)
		}
		if strings.HasPrefix(intStr, "-") {
			intStr = intStr[1:]
		}
		if len(fracStr) < fDigits {
			fracStr += strings.Repeat("0", fDigits-len(fracStr))
		}
		if len(fracStr) > fDigits {
			fracStr = fracStr[:fDigits]
		}
	} else {
		intStr = sFixed
		if strings.HasPrefix(intStr, "-") {
			intStr = intStr[1:]
		}
		fracStr = ""
	}
	if len(intStr) > iPlace {
		intStr = intStr[len(intStr)-iPlace:]
	}
	if len(intStr) < iPlace {
		intStr = strings.Repeat("0", iPlace-len(intStr)) + intStr
	}
	outInt := []rune(intPic)
	digitIdx := 0
	suppressed := true
	for i, ch := range intPic {
		if ch == ',' {
			if suppressed {
				outInt[i] = ' '
			} else {
				outInt[i] = ','
			}
		} else if ch == 'Z' || ch == '9' {
			d := intStr[digitIdx]
			digitIdx++
			if ch == 'Z' {
				if suppressed && d == '0' {
					outInt[i] = ' '
				} else {
					outInt[i] = rune(d)
					suppressed = false
				}
			} else {
				outInt[i] = rune(d)
				if d != '0' {
					suppressed = false
				}
			}
		}
	}
	if fDigits > 0 {
		return string(outInt) + "." + fracStr
	}
	return string(outInt)
}

func READ_PARA() {
	ReadPara()
}
func PROCESS_PARA() {
	ProcessPara()
}
func MAIN_PARA() {
	MainPara()
}

func ReadPara() {
	if taxScanner == nil {
		WsEofFlag = "Y"
		return
	}
	if taxScanner.Scan() {
		line := taxScanner.Text()
		if len(line) < 13 {
			line += strings.Repeat(" ", 13-len(line))
		} else if len(line) > 13 {
			line = line[:13]
		}
		taxRec.TrId = line[0:5]
		incomeRaw := line[5:13]
		cleaned := ""
		for _, c := range incomeRaw {
			if c >= '0' && c <= '9' {
				cleaned += string(c)
			} else {
				cleaned += "0"
			}
		}
		if strings.Trim(cleaned, "0") == "" {
			cleaned = "0"
		}
		n, err := strconv.ParseInt(cleaned, 10, 64)
		if err != nil {
			n = 0
		}
		taxRec.TrIncome = decimal.New(n, -2)
	} else {
		if err := taxScanner.Err(); err != nil {
			fmt.Fprintf(os.Stderr, "read error: %v\n", err)
			os.Exit(1)
		}
		WsEofFlag = "Y"
	}
}

func ProcessPara() {
	d10000 := decimal.NewFromInt(10000)
	d40000 := decimal.NewFromInt(40000)
	d1000 := decimal.NewFromInt(1000)
	d7000 := decimal.NewFromInt(7000)
	d10 := decimal.New(10, -2)
	d20 := decimal.New(20, -2)
	d30 := decimal.New(30, -2)

	var computed decimal.Decimal
	if taxRec.TrIncome.Cmp(d10000) <= 0 {
		computed = taxRec.TrIncome.Mul(d10)
		WsTax = computed.Round(2)
		WsTax = fitDecimal(WsTax, 7, 2)
	} else if taxRec.TrIncome.Cmp(d40000) <= 0 {
		diff := taxRec.TrIncome.Sub(d10000)
		computed = d1000.Add(diff.Mul(d20))
		WsTax = computed.Round(2)
		WsTax = fitDecimal(WsTax, 7, 2)
	} else {
		diff := taxRec.TrIncome.Sub(d40000)
		computed = d7000.Add(diff.Mul(d30))
		WsTax = computed.Round(2)
		WsTax = fitDecimal(WsTax, 7, 2)
	}
	netRaw := taxRec.TrIncome.Sub(WsTax)
	WsNet = netRaw.Truncate(2)
	WsNet = fitDecimal(WsNet, 7, 2)

	WsTotalTax = WsTotalTax.Add(WsTax)
	WsTotalTax = fitDecimal(WsTotalTax, 9, 2)

	WsCount++
	if WsCount >= 1000 {
		WsCount = WsCount % 1000
	}

	WsIncEd = formatEdited(taxRec.TrIncome, "ZZZ,ZZ9.99")
	WsTaxEd = formatEdited(WsTax, "ZZZ,ZZ9.99")
	WsNetEd = formatEdited(WsNet, "ZZZ,ZZ9.99")

	fmt.Printf("%s %s %s %s\n", taxRec.TrId, WsIncEd, WsTaxEd, WsNetEd)

	ReadPara()
}

func MainPara() {
	f, err := os.Open("input.dat")
	if err != nil {
		fmt.Fprintf(os.Stderr, "open input.dat: %v\n", err)
		os.Exit(1)
	}
	taxFile = f
	taxScanner = bufio.NewScanner(f)
	const maxCap = 1024 * 1024
	buf := make([]byte, 0, 64*1024)
	taxScanner.Buffer(buf, maxCap)
	taxScanner.Split(bufio.ScanLines)

	WsEofFlag = "N"
	WsTax = decimal.NewFromInt(0)
	WsNet = decimal.NewFromInt(0)
	WsTotalTax = decimal.NewFromInt(0)
	WsCount = 0

	ReadPara()
	for WsEofFlag != "Y" {
		ProcessPara()
	}
	if taxFile != nil {
		taxFile.Close()
	}
	WsTotalEd = formatEdited(WsTotalTax, "ZZ,ZZZ,ZZ9.99")
	countStr := fmt.Sprintf("%03d", WsCount%1000)
	fmt.Printf("TAXPAYERS: %s TOTAL TAX: %s\n", countStr, WsTotalEd)
}

func main() {
	MainPara()
}
